  static String get(Context c,String s){
    int language=BuilderLocale.index(c);
    if(s==null||language==0)return s;
    String[] row=map.get(s);
    if(row!=null)return row[language];
    for(String prefix:new String[]{"Файл: ","Нишона: ","Файл захира шуд: "})
      if(s.startsWith(prefix))return map.get(prefix)[language]+s.substring(prefix.length());
    return s;
  }
